-- 부천 행정동 37개 경계 (출처: 국가데이터처 SGIS 행정구역 경계, 기준일 20250630)
-- 좌표계: WGS84(SRID 4326). 테이블은 ERD의 dongs. 프론트용 경계는 data/bucheon_dong_light.geojson 파일을 쓴다.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS dongs (
  dong_code        CHAR(10)     PRIMARY KEY,   -- 통계청 행정구역분류 8자리(SGIS)를 넣는다
  name             VARCHAR(20)  NOT NULL,
  gu_name          VARCHAR(10)  NOT NULL,
  boundary         MULTIPOLYGON NOT NULL SRID 4326,
  boundary_version VARCHAR(8)   NOT NULL,
  SPATIAL INDEX (boundary)
) DEFAULT CHARSET=utf8mb4;  -- 동 이름이 한글이다. 서버 기본값이 다르면 이름이 깨진다


-- 적재 확인: 37이 나와야 한다
SELECT COUNT(*) FROM dongs;
-- 판정 확인: 축 순서를 명시한다(빼면 MySQL이 POINT(위도 경도)로 읽어 범위 오류가 난다)
SELECT dong_code, name, gu_name FROM dongs
WHERE ST_Contains(boundary, ST_GeomFromText('POINT(126.8016 37.4863)', 4326, 'axis-order=long-lat'));
